"""Opt-in exact mixed-Bundle sampling with authored and event anchors.

The existing anchored constructor retains every physical control and topology
event. Every original boundary sample remains in its continuous-error check;
sampling those boundaries does not make each approximation knot an output row.
This module changes eligibility only, never the profile or acceptance checks.
"""
from . import bundle_axis_nodes as axis


def eligibility(g, curves, owner, partner, boundary_records, query, lateral,
                minimum_band, free_cap, terminal_alignment, *, local_chart=False, physical_caps=False):
    def meta(name, kind, at):
        return g.sample(curves, g.named('st_sweep_'+name, kind), at, kind, 'CURVE')
    points = query(g.named('st_bundle_metric', 'FLOAT'))
    gap = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', points[2], points[1]), lateral)
    records = axis._join(g, *boundary_records)
    mixed = g.all(g.compare(g.stat(records, gap), minimum_band, 'LESS_THAN'),
                  g.compare(g.stat(records, gap, output='Max'), minimum_band, 'GREATER_THAN'))
    exact = g.all(*(g.compare(meta('interpolation', 'INT', at), 0, kind='INT')
                    for at in (owner, partner)))
    return g.all(exact, mixed, g.either(g.boolean('NOT', free_cap), physical_caps),
                 g.either(g.boolean('NOT', terminal_alignment), local_chart),
                 *(g.boolean('NOT', meta(side+'_attached', 'BOOLEAN', at))
                   for at in (owner, partner) for side in ('start', 'end')))


def install_saved(original):
    """Extend the saved v5 sampling predicate using the canonical eligibility."""
    from .path_surface_nodes import _Nodes
    from . import bundle_lookup_nodes
    if original.get('st_bundle_uniform_separated') != 5 or original.get('st_bundle_uniform_mixed'):
        raise ValueError('Expected an unextended v5 uniform Bundle primitive')
    tree = original.copy(); tree.name = original.name.replace(' v5 /', ' v6 /')
    g = _Nodes(tree)

    def named(label, kind=None):
        node, = [n for n in tree.nodes if n.label == label and (kind is None or n.type == kind)]
        return node

    def incoming(socket):
        value, = [link.from_socket for link in socket.links]
        return value

    def stored_value(name):
        node, = [n for n in tree.nodes if n.type == 'STORE_NAMED_ATTRIBUTE'
                 and n.inputs['Name'].default_value == name]
        return incoming(node.inputs['Value'])

    active = stored_value('st_bundle_regular_rows')
    assert active.node.bl_idname == 'FunctionNodeBooleanMath' and active.node.operation == 'OR'
    sampling = named('Certified regular rows for smooth event-free Bundle spans')
    assert incoming(sampling.inputs['Switch']) == active
    previous = incoming(active.node.inputs[1])
    destinations = [link.to_socket for link in previous.links]
    # Eligibility must select both the row geometry and its certificate.
    switches = [s.node for s in destinations if s.name == 'Switch' and s.node.type == 'SWITCH']
    assert any(n.input_type == 'GEOMETRY' for n in switches)
    assert any(n.input_type == 'BOOLEAN' for n in switches)
    lookups = [n for n in tree.nodes if n.type == 'GROUP' and n.node_tree
               and n.node_tree.name == 'Prochitecture Streets / Bundle boundary interpolation v1']
    curves = [incoming(lookups[0].inputs['Boundary '+str(k)]) for k in range(4)]
    assert all([incoming(n.inputs['Boundary '+str(k)]) for k in range(4)] == curves for n in lookups)
    records = [incoming(named('Monotone boundary '+str(k)+' physical-axis lookup').inputs['Geometry'])
               for k in range(4)]
    events = named('Certified local-difference Bundle topology events')
    lateral = incoming(events.inputs['Lateral'])
    minimum = incoming(events.inputs['Minimum Separator Width'])
    inp = next(n for n in tree.nodes if n.type == 'GROUP_INPUT')
    added = eligibility(g, inp.outputs['Curves'], inp.outputs['Owner'], inp.outputs['Partner'],
        records, lambda s: bundle_lookup_nodes.evaluate(g, curves, s), lateral, minimum,
        stored_value('st_bundle_free_cap_body'), stored_value('st_bundle_terminal_alignment'))
    combined = g.either(previous, added)
    for socket in destinations:
        g.set(combined, socket)
    tree['st_bundle_uniform_mixed'] = 1
    return tree


def cell_width_bounds(g, points, side_count, middle_count, minimum_band):
    """Conservative transverse widths for axial refinement, not a new profile.

    Above the separator threshold the bands use the physical inner edges.
    When the virtual band overrides the physical gap it is at most 0.4 times
    the shorter half-span, so each shoulder retains at least 0.8 of that
    half-span; otherwise the physical shoulder widths still apply. The minimum
    band W=f*(1-t*t+t*t*t) is at least 23*f/27. These lower bounds also cover
    the broadened overlap band; all actual cells still undergo their checks.
    """
    oa, ia, ib, ob = points[:4]
    cross = g.vector('SUBTRACT', ob, oa)
    left_b = g.compare(g.vector('DOT_PRODUCT', g.vector('SUBTRACT', ib, oa), cross), 0., 'LESS_THAN')
    right_a = g.compare(g.vector('DOT_PRODUCT', g.vector('SUBTRACT', ia, ob), cross), 0., 'GREATER_THAN')
    oa, ob = g.switch(left_b, oa, ib, 'VECTOR'), g.switch(right_a, ob, ia, 'VECTOR')
    direction = g.vector('NORMALIZE', g.vector('SUBTRACT', ob, oa))
    span = g.vector('DISTANCE', ob, oa)
    a = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', ia, oa), direction)
    b = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', ib, oa), direction)
    gap = g.math('SUBTRACT', b, a)
    right = g.math('SUBTRACT', span, b)
    a2, r2 = g.math('MULTIPLY', a, a), g.math('MULTIPLY', right, right)
    peak = g.math('DIVIDE', g.math('ADD', g.math('MULTIPLY', a, r2), g.math('MULTIPLY', b, a2)),
                  g.math('MAXIMUM', 1e-6, g.math('ADD', a2, r2)))
    middle = g.switch(g.compare(gap, 0., 'LESS_THAN'), g.math('MULTIPLY', .5, g.math('ADD', a, b)), peak)
    shorter = g.math('MINIMUM', middle, g.math('SUBTRACT', span, middle))
    shoulder = g.math('MULTIPLY', .8, shorter)
    floor = g.math('MULTIPLY', 23./27., g.math('MINIMUM', minimum_band, g.math('MULTIPLY', .4, shorter)))
    separated = g.compare(gap, minimum_band, 'GREATER_EQUAL')
    return [g.math('DIVIDE', g.switch(separated, low, physical), count)
            for low, physical, count in ((g.math('MINIMUM', shoulder, a), a, side_count),
                                         (floor, gap, middle_count),
                                         (g.math('MINIMUM', shoulder, right), right, side_count))]


def install_balance_saved(original):
    """Refine a saved v6 mixed candidate without changing its anchor sampling."""
    from .path_surface_nodes import _Nodes
    from . import bundle_lookup_nodes, bundle_row_balance_nodes
    if original.get('st_bundle_uniform_mixed') != 1:
        raise ValueError('Expected an unbalanced v6 exact mixed-Bundle primitive')
    tree = original.copy(); tree.name = original.name.replace(' v6 /', ' v7 /')
    g = _Nodes(tree)

    def named(label, kind=None):
        node, = [n for n in tree.nodes if n.label == label and (kind is None or n.type == kind)]
        return node

    def incoming(socket):
        value, = [link.from_socket for link in socket.links]
        return value

    regular, = [n for n in tree.nodes if n.type == 'STORE_NAMED_ATTRIBUTE'
                and n.inputs['Name'].default_value == 'st_bundle_regular_rows']
    combined = incoming(regular.inputs['Value'])
    extended = incoming(combined.node.inputs[1])
    assert combined.node.operation == extended.node.operation == 'OR'
    active = incoming(extended.node.inputs[1])
    counts = []
    for label in ('Owner shoulder direct quads', 'Separator or merged crown direct quads'):
        addition = incoming(named(label).inputs['Vertices X']).node
        assert addition.bl_idname == 'ShaderNodeMath' and addition.operation == 'ADD'
        assert addition.inputs[1].default_value == 1.
        counts.append(incoming(addition.inputs[0]))
    outer = named('st_bundle_outer_a', 'STORE_NAMED_ATTRIBUTE')
    table = incoming(outer.inputs['Geometry'])
    last = named('Final physical Bundle station')
    end, = [link.to_node for link in last.outputs['Mesh'].links if link.to_node.type == 'STORE_NAMED_ATTRIBUTE'
            and link.to_node.inputs['Name'].default_value == 'st_bundle_metric']
    length = incoming(end.inputs['Value'])
    lookups = [n for n in tree.nodes if n.type == 'GROUP' and n.node_tree
               and n.node_tree.name == 'Prochitecture Streets / Bundle boundary interpolation v1']
    curves = [incoming(lookups[0].inputs['Boundary '+str(k)]) for k in range(4)]
    assert all([incoming(n.inputs['Boundary '+str(k)]) for k in range(4)] == curves for n in lookups)
    mandatory = axis._join(g, *(incoming(named('Monotone boundary '+str(k)+' physical-axis lookup').inputs['Geometry'])
                               for k in range(4)))
    minimum = incoming(named('Certified local-difference Bundle topology events').inputs['Minimum Separator Width'])
    refined, valid = bundle_row_balance_nodes.construct(g, table, mandatory, length,
        lambda s: bundle_lookup_nodes.evaluate(g, curves, s), *counts, active,
        cell_widths=lambda p: cell_width_bounds(g, p, *counts, minimum))
    bounded = named('Bound whole Bundle allocation before three quad grids')
    size = incoming(bounded.inputs['True']).node
    assert size.bl_idname == 'GeometryNodeAttributeDomainSize' and incoming(size.inputs['Geometry']) == table
    budget = incoming(bounded.inputs['Switch']); destinations = [link.to_socket for link in budget.links]
    combined = g.all(budget, valid)
    for socket in destinations:
        g.set(combined, socket)
    g.set(refined, size.inputs['Geometry']); g.set(refined, outer.inputs['Geometry'])
    tree['st_bundle_uniform_mixed'] = 2
    return tree
